// Centralized termination — idempotent, no pile-up of SIGKILL timers.
// Kills the entire process group (negative PID) so any children of claude
// are reaped too. Falls back to killing just the leader if group-kill fails.
function hardKill(reason) {
  if (killReason) return;
  killReason = reason;
  const killSignal = (sig) => {
    try {
      if (proc.pid) process.kill(-proc.pid, sig);  // process group
    } catch {
      try { proc.kill(sig); } catch { /* already dead */ }
    }
  };
  killSignal('SIGTERM');
  sigkillTimer = setTimeout(() => killSignal('SIGKILL'), 5000);
  if (sigkillTimer && typeof sigkillTimer.unref === 'function') sigkillTimer.unref();
}

